/* Блочный элемент: auto = 100% ширины */
.block {
  width: auto; /* = 100% ширины родителя */
}

/* Центрирование через auto margin */
.centered {
  width: 300px;
  margin: 0 auto;
}

.parent {
  width: 600px;
  height: 400px;
}

.child {
  width: 50%;       /* 300px — половина ширины родителя */
  height: 50%;      /* 200px — половина высоты родителя */
  padding: 10%;     /* 60px — от ширины родителя (!) */
  margin: 5%;       /* 30px — от ширины родителя (!) */
}

/* img по умолчанию — inline, растягивается на всю строку */
img {
  max-width: 100%;  /* не шире родителя */
  height: auto;     /* сохраняет пропорции */
}

/* Абсолютно позиционированный элемент */
.absolute {
  position: absolute;
  width: 100%;  /* от ближайшего позиционированного предка */
  height: 100%; /* от ближайшего позиционированного предка */
}

.container {
  width: 80%;           /* основной размер */
  min-width: 300px;     /* не уже 300px */
  max-width: 1200px;    /* не шире 1200px */
}

/* Приоритет: min/max перезаписывают width/height */
.element {
  width: 500px;
  min-width: 600px; /* будет 600px, не 500px! */
}

/* Решение margin collapsing */
.parent {
  padding-top: 1px;  /* создаёт BFC */
  /* или */
  display: flex;     /* flex контейнер не схлопывает */
  /* или */
  overflow: hidden;  /* создаёт BFC */
}

/* min-content: минимальный размер без переноса */
.text {
  width: min-content;
}

/* max-content: максимальный размер без переноса */
.text {
  width: max-content;
}

/* fit-content: как max-content, но не шире родителя */
.text {
  width: fit-content(300px);
}

/* Проблема: flex-item не сжимается */
.flex-item {
  min-width: 0; /* разрешает сжатие ниже content size */
}

/* Проблема: overflow не работает без высоты */
.scrollable {
  height: 200px;    /* высота ОБЯЗАНА быть задана */
  overflow-y: auto;
}

/* Проблема: img не центрируется */
img {
  display: block;    /* убирает inline-пробелы */
  margin: 0 auto;
}
